//Template for running analyses using Lisa (does very little, as is)
//@category PCode



using ghidra.app.script;
using ghidra.lisa.pcode;
using ghidra.lisa.pcode.analyses;
using ghidra.lisa.pcode.locations;
using ghidra.util;
using it.unive.lisa;
using it.unive.lisa.analysis;
using it.unive.lisa.analysis.nonrelational.value;
using it.unive.lisa.interprocedural;
using it.unive.lisa.program;
using it.unive.lisa.program.cfg;
using it.unive.lisa.program.cfg.statement;
using it.unive.lisa.symbolic.value;
using it.unive.lisa.util.representation;

public class LisaLaunchScript : GhidraScript {

	/* @Override */
	public void run()
    {
		if (isRunningHeadless()) {
			popup("Script is not running in GUI");
			return;
		}

		PcodeFrontend frontend = new PcodeFrontend(state.getTool());
		Program p = frontend.doWork(currentProgram.getListing(), currentAddress, false);

		DefaultConfiguration conf = new DefaultConfiguration();
		conf.serializeResults = true;
		conf.abstractState = DefaultConfiguration.simpleState(
			DefaultConfiguration.defaultHeapDomain(),
			//new DefiniteDataflowDomain<>(new ConstantPropagation()),
			new(
				new PcodeByteBasedConstantPropagation(currentProgram.getLanguage())),
			DefaultConfiguration.defaultTypeDomain());
		LiSA lisa = new LiSA(conf);

		LiSAReport report = lisa.run(p);
		InterproceduralAnalysis<object> interproceduralAnalysis =
			report.getConfiguration().interproceduralAnalysis;
		Collection<CFG> ep = p.getEntryPoints();
		foreach (CFG cfg in ep) {
			Collection<object> results = interproceduralAnalysis.getAnalysisResultsOf(cfg);
			Iterator<object> iterator = results.iterator();
			while (_iterator.hasNext()) {
				object next = _iterator.next();
				if (next is AnalyzedCFG<object> acfg) {
					processCFG(cfg, acfg);
				}
			}
		}

	}

	private void processCFG(CFG cfg, AnalyzedCFG<object> acfg) {
		if (!cfg.getNodes().isEmpty()) {
			foreach (Statement st in cfg.getNodes()) {
				AnalysisState<object> s = acfg.getAnalysisStateAfter(st);
				AbstractState<object> abs = s.getState();
				if (abs is SimpleAbstractState sas) {
					processState(sas, st);
				}
			}
		}
	}

	/* @SuppressWarnings("rawtypes") */
	private void processState(SimpleAbstractState sas, Statement st) {
		ValueEnvironment<object> valueState =
			(ValueEnvironment<object>) sas.getValueState();
		//DefiniteDataflowDomain valueState = (DefiniteDataflowDomain) sas.getValueState();
		Map<Identifier,object> function = valueState.function;
		if (function != null) {
			foreach (object key in function.keySet()) {
				object val = valueState.function.get(key);
				exampleAnalysis(st, key, val);
			}
		}
	}

	private void exampleAnalysis(Statement st, object key, object val) {
		if (val is PcodeByteBasedConstantPropagation icp) {
			StructuredRepresentation representation =
				icp.representation();
			string rep = representation.toString();
			if (!rep.contains("TOP")) {
				PcodeLocation loc =
					(PcodeLocation) st.getLocation();
				Msg.info(this, loc.getCodeLocation() +
					" ==> " + key + ":" + representation);
			}
		}
	}

}
